import{_ as l,o as a,c as i,a2 as o}from"./chunks/framework.DNkSpPuX.js";const h=JSON.parse('{"title":"包生态总览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/package-ecosystem.md","filePath":"guide/package-ecosystem.md","lastUpdated":1794045200000}'),c={name:"guide/package-ecosystem.md"};function t(s,e,d,r,m,b){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="包生态总览" tabindex="-1">包生态总览 <a class="header-anchor" href="#包生态总览" aria-label="Permalink to &quot;包生态总览&quot;">​</a></h1><p>如果你是从 npm 入口进来的，不用一开始就把整套仓库结构看完。先记住这件事：</p><ul><li><code>@melt-js/libs-bag-entry</code> 负责宿主运行时</li><li><code>@melt-js/comps-bag-*</code> 负责具体业务能力</li><li><code>@melt-js/libs-bag-create</code> 负责把起步工程搭出来</li></ul><p>先这样记就够了。只有在你准备深入仓库内部实现时，才需要继续往下拆。</p><h2 id="对外怎么理解" tabindex="-1">对外怎么理解 <a class="header-anchor" href="#对外怎么理解" aria-label="Permalink to &quot;对外怎么理解&quot;">​</a></h2><p>现在对外的默认口径是：</p><ul><li><code>@melt-js/libs-bag-entry</code>：业务项目安装的主包</li><li><code>@melt-js/comps-bag-*</code>：按需安装的业务插件包</li><li><code>@melt-js/libs-bag-create</code>：生成宿主项目的脚手架</li></ul><p>使用方不用一开始就关心内部拆了多少层。先装主包，再按业务需要装插件。</p><h2 id="仓库内部怎么拆" tabindex="-1">仓库内部怎么拆 <a class="header-anchor" href="#仓库内部怎么拆" aria-label="Permalink to &quot;仓库内部怎么拆&quot;">​</a></h2><p>仓库内部还是分层的，这些分层主要服务实现和维护：</p><ul><li><code>@melt-js/libs-bag-core</code>：协议层，定义插件、路由 meta、菜单、Schema、字典这些公共约定</li><li><code>@melt-js/libs-bag-request</code>：请求层，处理 HTTP 和 WebSocket 接入</li><li><code>@melt-js/libs-bag-ui</code>：组件层，提供 <code>PmProTable</code>、<code>PmProForm</code>、<code>PmSchemaForm</code>、<code>PmDictTag</code></li><li><code>@melt-js/libs-bag-host</code>：宿主层，负责布局、权限、标签页、插件引导和 i18n 初始化</li><li><code>@melt-js/libs-bag-entry</code>：把前面几层收成业务项目更容易接入的主包</li><li><code>@melt-js/comps-bag-*</code>：业务插件层，把不同业务域拆成独立模块</li><li><code>@melt-js/libs-bag-create</code>：脚手架入口，生成宿主项目的起步工程</li></ul><p>如果你只是在用，不一定要把这些层都记牢。知道它们各自管什么就够了。</p><h2 id="先记住这几个角色" tabindex="-1">先记住这几个角色 <a class="header-anchor" href="#先记住这几个角色" aria-label="Permalink to &quot;先记住这几个角色&quot;">​</a></h2><p>想快速建立印象，可以先按这个版本理解：</p><ul><li><code>core</code> 管协议</li><li><code>request</code> 管请求</li><li><code>ui</code> 提供通用积木</li><li><code>host-vue</code> 把宿主真正跑起来</li><li><code>@melt-js/libs-bag-entry</code> 把前面几层打包成默认入口</li><li><code>plugin-*</code> 往宿主里挂业务</li><li><code>@melt-js/libs-bag-create</code> 帮你把项目先起出来</li></ul><h2 id="阅读顺序" tabindex="-1">阅读顺序 <a class="header-anchor" href="#阅读顺序" aria-label="Permalink to &quot;阅读顺序&quot;">​</a></h2><p>第一次接触这套项目，可以按这个顺序看：</p><ol><li><code>@melt-js/libs-bag-entry</code> / <code>@melt-js/libs-bag-create</code>：先看入口，知道正常使用姿势是什么</li><li><a href="./package-core.html">@melt-js/libs-bag-core</a>：再看插件协议和 Schema 协议到底长什么样</li><li><a href="./package-ui.html">@melt-js/libs-bag-ui</a>：理解这些协议怎么落到组件上</li><li><a href="./package-request.html">@melt-js/libs-bag-request</a>：补上请求层的接入方式</li><li><code>@melt-js/libs-bag-host</code>：再回头看宿主怎样把插件、布局、权限串起来</li><li><a href="./package-plugin-shop.html">@melt-js/comps-bag-shop</a> / <a href="./package-plugin-sys-setting.html">@melt-js/comps-bag-sys</a>：再看官方插件示例，会更容易代入</li></ol><p>这个顺序就是先看怎么用，再看内部为什么这么设计。</p><h2 id="这些包怎么串起来" tabindex="-1">这些包怎么串起来 <a class="header-anchor" href="#这些包怎么串起来" aria-label="Permalink to &quot;这些包怎么串起来&quot;">​</a></h2><p>从实际使用流程看，最常见的一条链路大概是这样：</p><ol><li>先用 <code>@melt-js/libs-bag-create</code> 生成一个宿主项目</li><li>生成后的项目默认安装 <code>@melt-js/libs-bag-entry</code></li><li>宿主项目通过 <code>@melt-js/libs-bag-entry</code> 初始化路由、布局、权限和插件系统</li><li>业务插件通过 <code>@melt-js/libs-bag-core</code> 约定 <code>AdminPlugin</code></li><li>插件页面通过 <code>@melt-js/libs-bag-ui</code> 复用表单、表格和字典组件</li><li>页面请求和实时消息通过 <code>@melt-js/libs-bag-request</code> 接入</li></ol><p>压缩成一句话就是：脚手架起项目，主包起宿主，插件补业务，底层分包分别负责协议、UI 和请求。</p><h2 id="已经补好的分包页" tabindex="-1">已经补好的分包页 <a class="header-anchor" href="#已经补好的分包页" aria-label="Permalink to &quot;已经补好的分包页&quot;">​</a></h2><p>目前已经补齐的分包文档有这些：</p><ul><li><a href="./package-core.html">@melt-js/libs-bag-core</a></li><li><a href="./package-request.html">@melt-js/libs-bag-request</a></li><li><a href="./package-ui.html">@melt-js/libs-bag-ui</a></li><li><a href="./package-plugin-shop.html">@melt-js/comps-bag-shop</a></li><li><a href="./package-plugin-sys-setting.html">@melt-js/comps-bag-sys</a></li></ul><p>如果你准备继续往下看，可以优先从 <code>core</code> 和 <code>ui</code> 开始。</p><p>如果你现在更关心维护者视角的实际操作，可以直接跳这两页：</p><ul><li><a href="./local-debugging.html">本地联调</a></li><li><a href="./package-publishing.html">发包流程</a></li></ul><h2 id="docs-和-readme-怎么分工" tabindex="-1">docs 和 README 怎么分工 <a class="header-anchor" href="#docs-和-readme-怎么分工" aria-label="Permalink to &quot;docs 和 README 怎么分工&quot;">​</a></h2><p>这两类文档现在是互补关系，不是二选一：</p><ul><li>包目录下的 <code>README.md</code>：更适合 npm 用户，重点放在安装、最小示例、公开能力和边界</li><li><code>docs-bag</code>：更适合顺着看，重点是概念串联、学习路径，以及这些包之间到底怎么配合</li></ul><p>第一次上手，先看 <code>docs-bag</code> 更顺。已经知道自己要接哪个包了，再去对应包的 <code>README.md</code> 会更快。</p>',33)])])}const g=l(c,[["render",t]]);export{h as __pageData,g as default};
